/**
 * Synonym lookups (genes, variants, drugs, cancer types), generated by `npm run synonyms` from HGNC, CIViC and the
 * NCI Thesaurus and filtered to terms present in our trials. See README.md for sources and licenses. Pure and
 * synchronous; every lookup is case-insensitive and returns an empty result for unknown terms.
 */
import diseasesJson from "./diseases.json";
import drugsJson from "./drugs.json";
import genesJson from "./genes.json";
import variantsJson from "./variants.json";

interface GeneRow {
  symbol: string;
  aliases: string[];
}
interface VariantRow {
  gene: string;
  name: string;
  aliases: string[];
}
interface DrugRow {
  name: string;
  names: string[];
  classes: string[];
}

const GENES = genesJson as GeneRow[];
const VARIANTS = variantsJson as VariantRow[];
const DRUGS = drugsJson as DrugRow[];
const DISEASES = diseasesJson as string[][];

/** Gene keys ignore case and punctuation so HER-2 = HER2 and PD-L1 = PDL1. */
const geneKey = (s: string) => s.toUpperCase().replace(/[^A-Z0-9]/g, "");
const textKey = (s: string) => s.toLowerCase().replace(/\s+/g, " ").trim();

function once<T>(build: () => T): () => T {
  let v: T | undefined;
  return () => (v ??= build());
}

const geneIndex = once(() => {
  const m = new Map<string, GeneRow>();
  for (const g of GENES) {
    m.set(geneKey(g.symbol), g);
    for (const a of g.aliases) if (!m.has(geneKey(a))) m.set(geneKey(a), g);
  }
  return m;
});
const variantIndex = once(() => {
  const m = new Map<string, VariantRow[]>();
  for (const v of VARIANTS) for (const k of [v.name, ...v.aliases]) (m.get(geneKey(k)) ?? m.set(geneKey(k), []).get(geneKey(k)))!.push(v);
  return m;
});
const drugIndex = once(() => {
  const m = new Map<string, DrugRow>();
  for (const d of DRUGS) {
    m.set(d.name, d);
    for (const n of d.names) if (!m.has(n)) m.set(n, d);
  }
  return m;
});
const diseaseIndex = once(() => {
  const m = new Map<string, string[][]>();
  for (const g of DISEASES) for (const t of g) (m.get(t) ?? m.set(t, []).get(t))!.push(g);
  return m;
});

/** Approved HGNC symbol for a gene symbol or alias ("HER2" -> "ERBB2", "PD-L1" -> "CD274"), else null. */
export function canonicalGene(alias: string): string | null {
  return geneIndex().get(geneKey(alias))?.symbol ?? null;
}

/** The symbol followed by its known aliases, or [] when the gene is unknown. */
export function geneNames(alias: string): string[] {
  const g = geneIndex().get(geneKey(alias));
  return g ? [g.symbol, ...g.aliases] : [];
}

/** CIViC variants matching a variant name or alias ("V600E" -> [{gene: "BRAF", name: "V600E"}]). */
export function canonicalVariant(alias: string): { gene: string; name: string }[] {
  return (variantIndex().get(geneKey(alias)) ?? []).map((v) => ({ gene: v.gene, name: v.name }));
}

/** Generic (NCIt preferred) drug name for a generic or brand name ("keytruda" -> "pembrolizumab"), else null. */
export function canonicalDrug(name: string): string | null {
  return drugIndex().get(textKey(name))?.name ?? null;
}

/** NCIt drug classes for a drug name, most specific first ("pembrolizumab" -> ["anti-PD-1", "PD-1 inhibitor"]). */
export function drugClass(name: string): string[] {
  return [...(drugIndex().get(textKey(name))?.classes ?? [])];
}

/** Other names for the same NCIt cancer type ("nsclc" -> ["non-small cell lung cancer", ...]), excluding the term. */
export function cancerSynonyms(term: string): string[] {
  const k = textKey(term);
  const out = new Set<string>();
  for (const g of diseaseIndex().get(k) ?? []) for (const t of g) if (t !== k) out.add(t);
  return [...out];
}

/**
 * Extra query words for keyword search. Conservative: a gene symbol or alias adds the other names of that gene, and a
 * brand or code name adds the generic drug name. Nothing is removed, and words already in the query are not repeated.
 */
export function expandQueryTerms(query: string): string[] {
  const words = query.split(/[\s,;()[\]{}"']+/).map((w) => w.replace(/^[.:]+|[.:]+$/g, "")).filter(Boolean);
  const have = new Set(words.map((w) => w.toLowerCase()));
  const extra: string[] = [];
  const add = (t: string) => {
    if (!have.has(t.toLowerCase())) {
      have.add(t.toLowerCase());
      extra.push(t);
    }
  };
  for (const w of words) {
    if (w.length < 3) continue;
    for (const n of geneNames(w)) add(n);
    const generic = canonicalDrug(w);
    if (generic) add(generic);
  }
  return extra;
}
